  ('10000001-0000-4000-8000-0016840182', '10000000-0000-4000-8000-0016840182', 'tr', 'randevu-sistemli-kurumsal-site', 'randevu sistemli kurumsal web siteleri geliştiririm', 'Klinik, spa, güzellik merkezi ve sağlık profesyonelleri için modern kurumsal web siteleri geliştiriyorum. Online randevu alma modülü, takvim entegrasyonu, çok dilli destek ve yapay zeka destekli sohbet botu (AI chatbot) dahil uçtan uca fullstack çözümler sunuyorum. Müşterileriniz 7/24 randevu alabilir, siz de tüm süreci admin panelinden yönetebilirsiniz.', '{"source":"bionluk","source_id":840182,"category":"Yazılım & Teknoloji > Web Yazılım","packages":[{"title":"Başlangıç Paketi","price":5000,"currency":"TRY","duration_days":7,"revisions":2,"description":"Tek dilli kurumsal tanıtım sitesi. Hizmet sayfaları ve iletişim formu dahil","options":[{"title":"Sayfa Sayısı","value":7,"unit":null},{"title":"Tasarım Özelleştirme","value":true,"unit":null},{"title":"İçerik Girişi","value":false,"unit":null},{"title":"Responsive Tasarım","value":true,"unit":null},{"title":"Kaynak Kodları","value":true,"unit":null}]},{"title":"Profesyonel Paket","price":10000,"currency":"TRY","duration_days":15,"revisions":5,"description":"Çok dilli kurumsal site + online randevu alma sistemi ve takvim yönetimi dahil.","options":[{"title":"Sayfa Sayısı","value":10,"unit":null},{"title":"Tasarım Özelleştirme","value":true,"unit":null},{"title":"İçerik Girişi","value":true,"unit":null},{"title":"Responsive Tasarım","value":true,"unit":null},{"title":"Kaynak Kodları","value":true,"unit":null}]},{"title":" Kurumsal Paket","price":20000,"currency":"TRY","duration_days":30,"revisions":7,"description":"Çok dilli kurumsal site + online randevu sistemi + yapay zeka destekli sohbet botu (AI Chatbot). Admin pa","options":[{"title":"Sayfa Sayısı","value":15,"unit":null},{"title":"Tasarım Özelleştirme","value":true,"unit":null},{"title":"İçerik Girişi","value":true,"unit":null},{"title":"Responsive Tasarım","value":true,"unit":null},{"t